using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using OpenAI;
using ResearchAgent;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build DI container ---
var services = new ServiceCollection();

services.AddSingleton(new OpenAIClient(apiKey));
services.AddSingleton<NoteService>();

services.AddChatClient(builder => builder
    .UseFunctionInvocation(options => options.MaximumIterationsPerRequest = 10)
    .UseOpenAIChatClient(modelId));

var serviceProvider = services.BuildServiceProvider();

// --- Define tools ---
var noteService = serviceProvider.GetRequiredService<NoteService>();
var chatClient = serviceProvider.GetRequiredService<IChatClient>();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
        {
            return WebSearchTool.SearchAsync(query);
        },
        "web_search",
        "Searches the web for information on a given query and returns relevant snippets."),

    AIFunctionFactory.Create(
        ([Description("The title or key for this note")] string title,
         [Description("The content to save")] string content) =>
        {
            noteService.AddNote(title, content);
            return $"Note saved: '{title}'";
        },
        "take_note",
        "Saves a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () => noteService.GetAllNotes(),
        "get_notes",
        "Retrieves all previously saved research notes."),
};

// --- Create agent ---
var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An AI research agent that searches the web and takes notes to summarize findings.",
    instructions: """
        You are a research agent. When given a topic:
        1. Search the web for relevant information using the web_search tool (make multiple searches to cover different aspects).
        2. Take notes on key findings using the take_note tool.
        3. After gathering enough information, retrieve your notes and produce a comprehensive summary.
        Be thorough but concise. Cite your sources where possible.
        """,
    tools: tools);

// --- Run the agent ---
Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.Write("> ");

while (Console.ReadLine() is { } input && !input.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(input))
    {
        Console.Write("> ");
        continue;
    }

    Console.WriteLine($"\nResearching: {input}\n");

    var runOptions = new ChatClientAgentRunOptions
    {
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
        },
    };

    try
    {
        var response = await agent.RunAsync(
            $"Research the following topic and provide a comprehensive summary: {input}",
            session: null,
            runOptions);

        Console.WriteLine("\n--- Research Summary ---\n");
        Console.WriteLine(response.Text);
        Console.WriteLine("\n--- End of Summary ---\n");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\nError: {ex.Message}\n");
    }

    noteService.Clear();
    Console.Write("> ");
}

