using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace ResearchAgent;

/// <summary>
/// Simulates web search using a free search API.
/// Replace with a real search provider (Bing, Google, Brave) for production use.
/// </summary>
public static class WebSearchTool
{
    private static readonly HttpClient HttpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            // Use DuckDuckGo Instant Answer API (free, no key required)
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

            var response = await HttpClient.GetFromJsonAsync<DuckDuckGoResponse>(url);

            if (response is null)
            {
                return "No results found.";
            }

            var results = new List<string>();

            if (!string.IsNullOrWhiteSpace(response.Abstract))
            {
                results.Add($"[Summary] {response.Abstract} (Source: {response.AbstractSource})");
            }

            if (!string.IsNullOrWhiteSpace(response.Answer))
            {
                results.Add($"[Answer] {response.Answer}");
            }

            if (response.RelatedTopics is { Count: > 0 })
            {
                foreach (var topic in response.RelatedTopics.Take(5))
                {
                    if (!string.IsNullOrWhiteSpace(topic.Text))
                    {
                        results.Add($"[Related] {topic.Text}");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try a more specific search.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try rephrasing the query.";
        }
    }

    private sealed class DuckDuckGoResponse
    {
        [JsonPropertyName("Abstract")]
        public string? Abstract { get; set; }

        [JsonPropertyName("AbstractSource")]
        public string? AbstractSource { get; set; }

        [JsonPropertyName("Answer")]
        public string? Answer { get; set; }

        [JsonPropertyName("RelatedTopics")]
        public List<RelatedTopic>? RelatedTopics { get; set; }
    }

    private sealed class RelatedTopic
    {
        [JsonPropertyName("Text")]
        public string? Text { get; set; }

        [JsonPropertyName("FirstURL")]
        public string? FirstURL { get; set; }
    }
}

namespace ResearchAgent;

/// <summary>
/// Simple in-memory note-taking service for the research agent.
/// </summary>
public sealed class NoteService
{
    private readonly List<ResearchNote> _notes = [];

    public void AddNote(string title, string content)
    {
        _notes.Add(new ResearchNote(title, content, DateTime.UtcNow));
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been taken yet.";
        }

        var formatted = _notes.Select((note, i) =>
            $"[{i + 1}] {note.Title}\n{note.Content}");

        return string.Join("\n\n", formatted);
    }

    public void Clear() => _notes.Clear();

    private sealed record ResearchNote(string Title, string Content, DateTime CreatedAt);
}

